```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg  [5:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    integer i;

    // Expected output task for checking
    task check_outputs(input [5:0] current_y, input current_w);
        reg exp_Y1;
        reg exp_Y3;
        begin
            // Derived from specification:
            // Y1 (next state B) = A --1--> B => y[0] & w
            exp_Y1 = (current_y[0] & current_w);

            // Y3 (next state D) = B--0-->D, C--0-->D, E--0-->D, F--0-->D => (y[1]|y[2]|y[4]|y[5]) & ~w
            exp_Y3 = ((current_y[1] | current_y[2] | current_y[4] | current_y[5]) & ~current_w);

            #1; // Allow propagation

            if (Y1 !== exp_Y1) begin
                $display("ERROR: y=%b, w=%b -> Y1 = %b, Expected = %b", current_y, current_w, Y1, exp_Y1);
                errors = errors + 1;
            end

            if (Y3 !== exp_Y3) begin
                $display("ERROR: y=%b, w=%b -> Y3 = %b, Expected = %b", current_y, current_w, Y3, exp_Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 6'b000000;
        w = 1'b0;
        #10;

        // Exhaustively test valid one-hot states with both w=0 and w=1
        // States: A (000001), B (000010), C (000100), D (001000), E (010000), F (100000)
        for (i = 0; i < 6; i = i + 1) begin
            y = (1 << i);
            w = 0;
            #5;
            check_outputs(y, w);

            w = 1;
            #5;
            check_outputs(y, w);
        end

        // Test non-one-hot or zero cases just to ensure robustness
        y = 6'b000000; w = 0; #5; check_outputs(y, w);
        y = 6'b000000; w = 1; #5; check_outputs(y, w);
        y = 6'b111111; w = 0; #5; check_outputs(y, w);
        y = 6'b111111; w = 1; #5; check_outputs(y, w);

        // Final status report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
```

